# Adaptive Rejection Sampling (ARS) implementation in R
# Based on Gilks & Wild (1992)

# Helper: numerical derivative or log-concavity check
# Log-concavity check: for points x1 < x2 < x3, log-density h(x) must satisfy chord condition:
# (h(x3) - h(x2)) / (x3 - x2) <= (h(x2) - h(x1)) / (x2 - x1)
check_log_concavity <- function(x_sorted, h_vals) {
  if (length(x_sorted) < 3) return(TRUE)
  for (i in 2:(length(x_sorted) - 1)) {
    x1 <- x_sorted[i-1]
    x2 <- x_sorted[i]
    x3 <- x_sorted[i+1]
    h1 <- h_vals[i-1]
    h2 <- h_vals[i]
    h3 <- h_vals[i+1]
    slope1 <- (h2 - h1) / (x2 - x1)
    slope2 <- (h3 - h2) / (x3 - x2)
    # slope2 should be <= slope1 for log-concavity
    if (slope2 > slope1 + 1e-7) {
      return(FALSE)
    }
  }
  return(TRUE)
}

# Initialize ARS envelope
ars_init <- function(h_func, h_prime_func, domain, x_init = NULL) {
  xmin <- domain[1]
  xmax <- domain[2]

  if (is.null(x_init)) {
    # Choose initial points in domain
    if (is.finite(xmin) && is.finite(xmax)) {
      x_init <- sort(c(xmin + 0.2*(xmax-xmin), xmin + 0.5*(xmax-xmin), xmin + 0.8*(xmax-xmin)))
    } else if (is.finite(xmin)) {
      x_init <- c(xmin + 0.5, xmin + 1.5, xmin + 2.5)
    } else if (is.finite(xmax)) {
      x_init <- c(xmax - 2.5, xmax - 1.5, xmax - 0.5)
    } else {
      x_init <- c(-1, 0, 1)
    }
  }

  x <- sort(unique(x_init))
  if (length(x) < 2) stop("At least 2 initial points required.")

  # Evaluate h(x) = log(f(x))
  h_vals <- sapply(x, h_func)
  if (any(!is.finite(h_vals))) {
    stop("Initial points must yield finite log-density values.")
  }

  # Evaluate derivatives h'(x)
  if (!is.null(h_prime_func)) {
    h_prime <- sapply(x, h_prime_func)
  } else {
    # Numerical derivative
    eps <- 1e-6
    h_prime <- sapply(x, function(xi) (h_func(xi + eps) - h_func(xi - eps)) / (2 * eps))
  }

  list(x = x, h_vals = h_vals, h_prime = h_prime, xmin = xmin, xmax = xmax)
}

# Construct upper envelope u(x) and lower envelope l(x)
# For ARS, upper envelope is piecewise linear in h (piecewise exponential in f)
# Defined by tangents at evaluation points x_k

# Sample from upper envelope
sample_upper <- function(env) {
  x <- env$x
  h <- env$h_vals
  hp <- env$h_prime
  xmin <- env$xmin
  xmax <- env$xmax

  k <- length(x)
  # Find intersection points z of tangents
  # tangent j: u_j(x) = h(j) + hp(j)*(x - x(j))
  # intersection z_j between j and j+1:
  # h(j) + hp(j)*(z - x(j)) = h(j+1) + hp(j+1)*(z - x(j+1))
  z <- numeric(k + 1)
  z[1] <- xmin
  z[k + 1] <- xmax

  for (j in 1:(k - 1)) {
    num <- h[j+1] - h[j] - hp[j+1]*x[j+1] + hp[j]*x[j]
    den <- hp[j] - hp[j+1]
    if (abs(den) < 1e-12) {
      z[j+1] <- (x[j] + x[j+1]) / 2
    } else {
      z[j+1] <- num / den
    }
    # Ensure z[j+1] is between x[j] and x[j+1]
    if (z[j+1] <= x[j] || z[j+1] >= x[j+1]) {
      z[j+1] <- (x[j] + x[j+1]) / 2
    }
  }

  # Calculate integral of exp(u(x)) on each interval [z_j, z_{j+1}]
  # On [z_j, x_j] and [x_j, z_{j+1}], u(x) is linear: u(x) = a_j + b_j * x
  # We integrate exp(u(x)) dx
  integrals <- numeric(k)
  for (j in 1:k) {
    # interval [z[j], z[j+1]]
    # slope is hp[j]
    # let's integrate exp( h[j] + hp[j]*(x - x[j]) ) dx from z[j] to z[j+1]
    # = exp(h[j] - hp[j]*x[j]) * [ exp(hp[j]*z[j+1]) - exp(hp[j]*z[j]) ] / hp[j] (if hp[j] != 0)
    # If hp[j] == 0, exp(h[j]) * (z[j+1] - z[j])
    b <- hp[j]
    c_val <- h[j] - b * x[j]
    z_left <- z[j]
    z_right <- z[j+1]

    # Handle infinite bounds safely
    if (is.infinite(z_left) || is.infinite(z_right)) {
      # If semi-infinite interval, require appropriate sign of b
      if (z_left == -Inf && b <= 0) stop("Upper envelope not integrable on (-Inf, ...)")
      if (z_right == Inf && b >= 0) stop("Upper envelope not integrable on (..., Inf)")
    }

    if (abs(b) < 1e-12) {
      integrals[j] <- exp(c_val) * (z_right - z_left)
    } else {
      # To avoid overflow, factor out max exponent
      # exp(c + b*z_right) - exp(c + b*z_left)
      # = exp(c + b*mid) * (exp(b*(z_right - mid)) - exp(b*(z_left - mid)))
      mid <- (z_left + z_right) / 2
      if (!is.finite(mid)) mid <- 0
      term1 <- c_val + b * mid
      term2 <- exp(b * (z_right - mid)) - exp(b * (z_left - mid))
      integrals[j] <- exp(term1) * term2 / b
    }
    if (!is.finite(integrals[j]) || integrals[j] < 0) {
      integrals[j] <- 1e-12
    }
  }

  total_int <- sum(integrals)
  probs <- integrals / total_int

  # Sample interval
  chosen_int <- sample.int(k, 1, prob = probs)

  # Sample x from truncated exponential on [z[chosen_int], z[chosen_int+1]] with slope hp[chosen_int]
  j <- chosen_int
  b <- hp[j]
  c_val <- h[j] - b * x[j]
  z_l <- z[j]
  z_r <- z[j+1]

  u_rand <- runif(1)

  if (abs(b) < 1e-12) {
    x_sample <- z_l + u_rand * (z_r - z_l)
  } else {
    # CDF of exp(c + b*x) from z_l to x is (exp(b*x) - exp(b*z_l)) / (exp(b*z_r) - exp(b*z_l))
    # Solve for x:
    # exp(b*x) = exp(b*z_l) + u_rand * (exp(b*z_r) - exp(b*z_l))
    # x = (1/b) * log( exp(b*z_l) + u_rand * (exp(b*z_r) - exp(b*z_l)) )
    # To prevent overflow when b*z_r is large, use log1p or log-sum-exp
    # Here let's do numerically stable formulation:
    # Let a_max = b * z_l (or b*z_r)
    # exp(b*x) = exp(b*z_l) * (1 - u_rand) + u_rand * exp(b*z_r)  if b > 0 etc.
    # More simply:
    val <- log(exp(b * z_l) + u_rand * (exp(b * z_r) - exp(b * z_l)))
    x_sample <- val / b
  }

  if (!is.finite(x_sample)) {
    x_sample <- x[j]
  }

  list(x = x_sample, interval = j, z = z)
}

# Evaluate upper envelope u(x)
eval_u <- function(x_eval, env) {
  x <- env$x
  h <- env$h_vals
  hp <- env$h_prime
  k <- length(x)

  # Find which interval x_eval falls into
  # Construct z as in sample_upper
  z <- numeric(k + 1)
  z[1] <- env$xmin
  z[k + 1] <- env$xmax
  for (j in 1:(k - 1)) {
    den <- hp[j] - hp[j+1]
    if (abs(den) < 1e-12) {
      z[j+1] <- (x[j] + x[j+1]) / 2
    } else {
      z[j+1] <- (h[j+1] - h[j] - hp[j+1]*x[j+1] + hp[j]*x[j]) / den
    }
    if (z[j+1] <= x[j] || z[j+1] >= x[j+1]) z[j+1] <- (x[j] + x[j+1]) / 2
  }

  # Find interval index
  j <- findInterval(x_eval, z)
  if (j < 1) j <- 1
  if (j > k) j <- k

  h[j] + hp[j] * (x_eval - x[j])
}

# Evaluate lower envelope l(x)
# Lower envelope is piecewise linear connecting (x_j, h(x_j))
eval_l <- function(x_eval, env) {
  x <- env$x
  h <- env$h_vals
  k <- length(x)
  if (x_eval <= x[1] || x_eval >= x[k]) return(-Inf)

  j <- findInterval(x_eval, x)
  if (j < 1) j <- 1
  if (j >= k) j <- k-1

  # Linear interpolation between x[j] and x[j+1]
  h[j] + (h[j+1] - h[j]) / (x[j+1] - x[j]) * (x_eval - x[j])
}

# Main ARS function
ars <- function(density_function, domain, n = 1000, h_prime_func = NULL, x_init = NULL) {
  # Input validation
  if (!is.function(density_function)) {
    stop("density_function must be a function.")
  }
  if (!is.numeric(domain) || length(domain) != 2 || domain[1] >= domain[2]) {
    stop("domain must be a numeric vector of length 2 with domain[1] < domain[2].")
  }
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || n %% 1 != 0) {
    stop("n (sample count) must be a positive integer.")
  }

  # Wrap density function to log-density h(x) = log(f(x))
  h_func <- function(x) {
    val <- density_function(x)
    if (any(val <= 0 | !is.finite(val))) return(-Inf)
    log(val)
  }

  # Initialize envelope
  env <- ars_init(h_func, h_prime_func, domain, x_init)

  samples <- numeric(n)
  count <- 0
  max_iters <- n * 50
  iter <- 0

  while (count < n && iter < max_iters) {
    iter <- iter + 1

    # 1. Sample from upper envelope
    s_res <- sample_upper(env)
    x_star <- s_res$x

    # Check domain bounds
    if (x_star < env$xmin || x_star > env$xmax) next

    # Evaluate h(x_star) and h'(x_star)
    h_star <- h_func(x_star)
    if (!is.finite(h_star)) next

    if (!is.null(h_prime_func)) {
      hp_star <- h_prime_func(x_star)
    } else {
      eps <- 1e-6
      hp_star <- (h_func(x_star + eps) - h_func(x_star - eps)) / (2 * eps)
    }

    u_val <- eval_u(x_star, env)
    l_val <- eval_l(x_star, env)

    w <- runif(1)

    # 2. Squeezing test
    if (log(w) <= l_val - u_val) {
      # Accept without evaluating density
      count <- count + 1
      samples[count] <- x_star
      # Update envelope with x_star anyway to improve approximation
      new_x <- sort(c(env$x, x_star))
      new_h <- sapply(new_x, h_func)
      if (!check_log_concavity(new_x, new_h)) {
        stop("Non-log-concave density detected during sampling (failed log-concavity check).")
      }
      env$x <- new_x
      env$h_vals <- new_h
      if (!is.null(h_prime_func)) {
        env$h_prime <- sapply(new_x, h_prime_func)
      } else {
        env$h_prime <- sapply(new_x, function(xi) (h_func(xi + 1e-6) - h_func(xi - 1e-6)) / (2 * 1e-6))
      }
      next
    }

    # 3. Rejection test
    if (log(w) <= h_star - u_val) {
      count <- count + 1
      samples[count] <- x_star
    }

    # Update envelope
    new_x <- sort(c(env$x, x_star))
    new_h <- sapply(new_x, h_func)
    if (!check_log_concavity(new_x, new_h)) {
      stop("Non-log-concave density detected during sampling (failed log-concavity check).")
    }
    env$x <- new_x
    env$h_vals <- new_h
    if (!is.null(h_prime_func)) {
      env$h_prime <- sapply(new_x, h_prime_func)
    } else {
      env$h_prime <- sapply(new_x, function(xi) (h_func(xi + 1e-6) - h_func(xi - 1e-6)) / (2 * 1e-6))
    }
  }

  if (count < n) {
    warning("Reached max iterations before generating all requested samples.")
    samples <- samples[1:count]
  }

  return(samples)
}

# Test function complying with requirements
test <- function() {
  cat("Running Adaptive Rejection Sampling (ARS) tests...\n\n")
  all_passed <- TRUE

  # Test 1: Normal distribution
  tryCatch({
    set.seed(42)
    d_norm <- function(x) dnorm(x, mean = 0, sd = 1)
    samples_norm <- ars(d_norm, domain = c(-4, 4), n = 1000, x_init = c(-1.5, 0, 1.5))
    mean_val <- mean(samples_norm)
    sd_val <- sd(samples_norm)

    # Expected mean ~ 0, sd ~ 1
    if (abs(mean_val) < 0.2 && abs(sd_val - 1) < 0.2 && length(samples_norm) == 1000) {
      cat(sprintf("NORMAL_DISTRIBUTION_TEST: PASS (mean = %.4f, sd = %.4f)\n", mean_val, sd_val))
      writeLines(as.character(samples_norm), "/app/normal_samples.txt")
    } else {
      cat(sprintf("NORMAL_DISTRIBUTION_TEST: FAIL (mean = %.4f, sd = %.4f)\n", mean_val, sd_val))
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("NORMAL_DISTRIBUTION_TEST: FAIL (Error: %s)\n", e$message))
    all_passed <- FALSE
  })

  # Test 2: Exponential distribution
  tryCatch({
    set.seed(42)
    d_exp <- function(x) dexp(x, rate = 1)
    samples_exp <- ars(d_exp, domain = c(0.01, 10), n = 1000, x_init = c(0.5, 2, 4))
    mean_val <- mean(samples_exp)
    sd_val <- sd(samples_exp)

    # Expected mean ~ 1, sd ~ 1 for exp(rate=1)
    if (abs(mean_val - 1) < 0.2 && abs(sd_val - 1) < 0.2 && length(samples_exp) == 1000) {
      cat(sprintf("EXPONENTIAL_DISTRIBUTION_TEST: PASS (mean = %.4f, sd = %.4f)\n", mean_val, sd_val))
      writeLines(as.character(samples_exp), "/app/exponential_samples.txt")
    } else {
      cat(sprintf("EXPONENTIAL_DISTRIBUTION_TEST: FAIL (mean = %.4f, sd = %.4f)\n", mean_val, sd_val))
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("EXPONENTIAL_DISTRIBUTION_TEST: FAIL (Error: %s)\n", e$message))
    all_passed <- FALSE
  })

  # Test 3: Input validation (negative sample count)
  tryCatch({
    ars(function(x) dnorm(x), c(-3, 3), n = -10)
    cat("INPUT_VALIDATION_TEST_N: FAIL (Should have rejected negative n)\n")
    all_passed <- FALSE
  }, error = function(e) {
    cat("INPUT_VALIDATION_TEST_N: PASS (Correctly caught negative n)\n")
  })

  # Test 4: Input validation (invalid domain)
  tryCatch({
    ars(function(x) dnorm(x), c(3, -3), n = 100)
    cat("INPUT_VALIDATION_TEST_DOMAIN: FAIL (Should have rejected invalid domain)\n")
    all_passed <- FALSE
  }, error = function(e) {
    cat("INPUT_VALIDATION_TEST_DOMAIN: PASS (Correctly caught invalid domain)\n")
  })

  # Test 5: Non-log-concave density check (e.g. Student's t or mixture of normals which is non-log-concave)
  tryCatch({
    # Mixture of two normals is not log-concave
    d_mix <- function(x) 0.5 * dnorm(x, -2, 0.5) + 0.5 * dnorm(x, 2, 0.5)
    ars(d_mix, c(-5, 5), n = 100, x_init = c(-3, 0, 3))
    cat("NON_LOG_CONCAVE_TEST: FAIL (Should have detected non-log-concave density)\n")
    all_passed <- FALSE
  }, error = function(e) {
    cat(sprintf("NON_LOG_CONCAVE_TEST: PASS (Correctly detected non-log-concave density: %s)\n", e$message))
  })

  cat("\nSummary:\n")
  if (all_passed) {
    cat("ALL TESTS PASSED\n")
  } else {
    cat("SOME TESTS FAILED\n")
  }
}
